            >
            Back
          </span>
          <v-icon size="12" color="#fdba74">mdi-chevron-right</v-icon>
          <v-icon size="14" color="#f97316">mdi-home</v-icon>
          <span>Ministry of Health</span>
          <v-icon size="12" color="#fdba74">mdi-chevron-right</v-icon>
          <span>Performance Management</span>
          <v-icon size="12" color="#fdba74">mdi-chevron-right</v-icon>
          <span class="pp2-hero__breadcrumb-active">Planning</span>
          <v-spacer></v-spacer>
          <span class="white--text font-weight-bold">
            {{ loggedInStaff.name }}</span
          >
          <span
            v-if="
              perfConfig &&
                !goalWindowOpen &&
                ['submitted', 'approved', 'undersupervisorreview'].includes(
                  planStatus,
                ) &&
                !windowClosedDismissed
            "
            class="pp2-hero__window-chip"
          >
            <v-icon size="11" color="#9ca3af">mdi-calendar-lock</v-icon>
            Window closed
            <button
              class="pp2-hero__window-chip-close"
              @click="windowClosedDismissed = true"
              title="Dismiss"
            >
              <v-icon size="10" color="#9ca3af">mdi-close</v-icon>
            </button>
          </span>
        </div>

        <div class="pp2-hero__content">
          <div class="pp2-hero__left">
            <div class="pp2-hero__badge">
              <v-icon size="14" color="#f97316"
                >mdi-chart-timeline-variant</v-icon
              >
              Annual Performance Plan
            </div>
            <div class="pp2-hero__title-row">
              <h1 class="pp2-hero__title">
                {{
                  performancePlan
                    ? performancePlan.name
                    : "Performance Planning"
                }}
              </h1>
              <button
                v-if="performancePlan && canEdit"
                class="pp2-hero__edit-btn"
                @click="editPlan"
                title="Edit Plan"
              >
                <v-icon size="14" color="rgba(255,255,255,0.7)"
                  >mdi-pencil</v-icon
                >
                Edit
              </button>
            </div>
            <div class="pp2-hero__meta">
              <div class="pp2-hero__meta-sep"></div>
              <div class="pp2-hero__meta-item">
                <v-icon size="15" color="#fdba74">mdi-calendar</v-icon>
                <span>FY {{ selectedFiscalYear }}</span>
              </div>
              <div v-if="performancePlan" class="pp2-hero__meta-sep"></div>
              <div
                v-if="performancePlan"
                class="pp2-hero__status"
                :class="`pp2-hero__status--${planStatus}`"
              >
                {{ statusLabel }}
              </div>
            </div>
          </div>

          <div class="pp2-hero__right">
            <div v-if="performancePlan" class="pp2-hero__stats">
              <div class="pp2-hero__stat">
                <div class="pp2-hero__stat-num">{{ objectives.length }}</div>
                <div class="pp2-hero__stat-label">Objectives</div>
              </div>
              <div class="pp2-hero__stat-div"></div>
              <div class="pp2-hero__stat">
                <div class="pp2-hero__stat-num">{{ activities.length }}</div>
                <div class="pp2-hero__stat-label">Activities</div>
              </div>
              <div class="pp2-hero__stat-div"></div>
              <div class="pp2-hero__stat">
                <div class="pp2-hero__stat-num">{{ kpis.length }}</div>
                <div class="pp2-hero__stat-label">KPIs</div>
              </div>
              <div class="pp2-hero__stat-div"></div>
              <div class="pp2-hero__stat">
                <div class="pp2-hero__stat-num">{{ targets.length }}</div>
                <div class="pp2-hero__stat-label">Targets</div>
              </div>
            </div>

            <div class="pp2-hero__actions">
              <div class="pp2-year-tabs">
                <button
                  v-for="yr in fiscalYears"
                  :key="yr"
                  class="pp2-year-tab"
                  :class="{ 'pp2-year-tab--active': selectedFiscalYear === yr }"
                  @click="
                    selectedFiscalYear = yr;
                    customFiscalYearInput = '';
                    loadPlan();
                  "
                >
                  {{ yr }}
                </button>
                <div class="pp2-year-custom">
                  <input
                    v-model="customFiscalYearInput"
                    class="pp2-year-custom__input"
                    :class="{
                      'pp2-year-custom__input--active':
                        selectedFiscalYear === customFiscalYearInput &&
                        customFiscalYearInput,
                      'pp2-year-custom__input--error': customFiscalYearError,
                    }"
                    placeholder="YYYY/YYYY"
                    maxlength="9"
                    @keyup.enter="applyCustomFiscalYear"
                    @blur="applyCustomFiscalYear"
                    title="Enter custom fiscal year (e.g. 2020/2021)"
                  />
                  <span
                    v-if="customFiscalYearError"
                    class="pp2-year-custom__err"
                  >
                    {{ customFiscalYearError }}
                  </span>
                </div>
              </div>
              <button class="pp2-icon-btn" @click="refreshData" title="Refresh">
                <v-icon size="18" color="rgba(255,255,255,0.7)"
                  >mdi-refresh</v-icon
                >
              </button>
            </div>
          </div>
        </div>
      </div>
    </header>

    <!-- Main Body -->
    <div class="pp2-body">
      <!-- Empty State -->
      <!-- Config window closed banner — only shown when plan still needs action -->
      <v-alert
        v-if="
          perfConfig &&
            !goalWindowOpen &&
            !['submitted', 'approved', 'undersupervisorreview'].includes(
              planStatus,
            )
        "
        type="warning"
        outlined
        dense
        class="pp2-window-alert"
      >
        <v-icon small left>mdi-calendar-lock</v-icon>
        <strong>Goal Setting Window Closed.</strong>
        {{ goalWindowMessage }}
        <span v-if="perfConfig.hasOverride">
          An extension is active for FY {{ perfConfig.targetFY }}.</span
        >
      </v-alert>
      <div v-if="isOwner && !performancePlan && canEdit" class="pp2-empty">
        <div class="pp2-empty__card">
          <div class="pp2-empty__illustration">
            <div class="pp2-empty__circle pp2-empty__circle--1"></div>
            <div class="pp2-empty__circle pp2-empty__circle--2"></div>
            <div class="pp2-empty__circle pp2-empty__circle--3"></div>
            <v-icon size="56" color="#f97316" class="pp2-empty__icon"
              >mdi-chart-gantt</v-icon
            >
          </div>
          <h2 class="pp2-empty__title">Start Your Performance Journey</h2>
          <p class="pp2-empty__desc">
            Create your performance plan for
            <strong>FY {{ selectedFiscalYear }}</strong> to define objectives,
            activities, and measurable targets aligned with Ministry priorities.
          </p>
          <button class="pp2-btn pp2-btn--primary" @click="createNewPlan">
            <v-icon left size="18">mdi-plus-circle-outline</v-icon>
            Create Performance Plan
          </button>
        </div>
      </div>

      <div
        v-else-if="!performancePlan && currentFiscalYear !== selectedFiscalYear"
        class="pp2-empty"
      >
        <div class="pp2-empty__card">
          <div class="pp2-empty__illustration">
            <div class="pp2-empty__circle pp2-empty__circle--1"></div>
            <div class="pp2-empty__circle pp2-empty__circle--2"></div>
            <div class="pp2-empty__circle pp2-empty__circle--3"></div>
            <v-icon size="56" color="#f97316" class="pp2-empty__icon"
              >mdi-chart-gantt</v-icon
            >
          </div>
          <h2 class="pp2-empty__title">No performance Plan for This Year</h2>
          <p class="pp2-empty__desc">
            You dont have performance plan for
            <strong>FY {{ selectedFiscalYear }}</strong>
          </p>
        </div>
      </div>

      <!-- Plan Content -->
      <div v-else class="pp2-content">
        <!-- Toolbar -->
        <div class="pp2-toolbar">
          <div class="pp2-toolbar__left">
            <div class="pp2-toolbar__crumb">
              <v-icon size="14" color="#f97316">mdi-target</v-icon>
              <span>{{ objectives.length }} Objectives</span>
            </div>
            <div class="pp2-toolbar__crumb">
              <v-icon size="14" color="#6366f1">mdi-run-fast</v-icon>
              <span>{{ activities.length }} Activities</span>
            </div>
            <div class="pp2-toolbar__crumb">
              <v-icon size="14" color="#6366f1">mdi-chart-bar</v-icon>
              <span>{{ kpis.length }} KPIs</span>
            </div>
            <div class="pp2-toolbar__crumb">
              <v-icon size="14" color="#10b981">mdi-bullseye-arrow</v-icon>
              <span>{{ targets.length }} Targets</span>
            </div>
          </div>
          <div class="pp2-toolbar__right">
            <button
              v-if="canEdit"
              class="pp2-btn pp2-btn--outline pp2-btn--sm"
              @click="addObjective"
