                :class="
                  planCanSubmit ? 'pp2-btn--primary' : 'pp2-btn--submit-blocked'
                "
                @click="showSubmitPlanDialog = true"
                :disabled="!planCanSubmit"
              >
                <v-icon left size="14">{{
                  planCanSubmit ? "mdi-send" : "mdi-alert-circle"
                }}</v-icon>
                <template v-if="isPrincipalSecretary">
                  Publish Plan
                </template>
                <template v-else>
                  Submit plan
                </template>
                <span v-if="!planCanSubmit" class="pp2-submit-error-badge">
                  {{ allPlanErrors.length }}
                </span>
              </button>
              <button
                v-if="!planCanSubmit"
                class="pp2-btn-check-issues"
                @click="showValidationPanel = !showValidationPanel"
                :title="showValidationPanel ? 'Hide issues' : 'Show issues'"
              >
                <v-icon size="14" color="#dc2626">{{
                  showValidationPanel ? "mdi-chevron-up" : "mdi-chevron-down"
                }}</v-icon>
              </button>
            </div>
          </div>
        </div>

        <!-- Validation Panel -->
        <transition name="pp2-slide">
          <div
            v-if="showValidationPanel && allPlanErrors.length > 0"
            class="pp2-validation-panel"
          >
            <div class="pp2-validation-panel__head">
              <v-icon size="16" color="#dc2626">mdi-alert-circle</v-icon>
              <span
                >{{ allPlanErrors.length }} issue{{
                  allPlanErrors.length !== 1 ? "s" : ""
                }}
                to fix before submitting</span
              >
              <button
                class="pp2-validation-panel__close"
                @click="showValidationPanel = false"
              >
                <v-icon size="16" color="#6b7280">mdi-close</v-icon>
              </button>
            </div>
            <div class="pp2-validation-panel__body">
              <div
                v-for="oc in objectivesWithErrors"
                :key="oc.objective.id"
                class="pp2-validation-obj"
              >
                <div class="pp2-validation-obj__title">
                  <v-icon size="13" color="#dc2626">mdi-target</v-icon>
                  {{ oc.objective.name }}
                </div>
                <ul class="pp2-validation-obj__errors">
                  <li v-for="(err, i) in oc.errors" :key="i">
                    <v-icon size="11" color="#dc2626">mdi-circle-small</v-icon>
                    {{ err.message }}
                  </li>
                </ul>
              </div>
            </div>
          </div>
        </transition>

        <!-- Objectives (loading, empty state, and grid all handled inside component) -->

        <div v-if="reviews.length > 0" class="pr-section">
          <div class="pr-section__head">
            <v-icon size="16" color="#0d9488">mdi-history</v-icon>
            <span class="pr-section__title">Approval History</span>
            <span class="pr-section__count"
              >{{ reviews.length }} review{{
                reviews.length !== 1 ? "s" : ""
              }}</span
            >
          </div>
          <div class="pr-reviews-list">
            <div
              v-for="(review, rIdx) in reviews"
              :key="review.id"
              class="pr-review-card"
              :class="`pr-review-card--${review.decision}`"
            >
              <div class="pr-review-card__header" @click="toggleReview(rIdx)">
                <div class="pr-review-card__header-left">
                  <div
                    class="pr-review-decision-icon"
                    :class="`pr-review-decision-icon--${review.decision}`"
                  >
                    <v-icon
                      size="14"
                      :color="
                        review.decision === 'approved' ? '#059669' : '#dc2626'
                      "
                    >
                      {{
                        review.decision === "approved"
                          ? "mdi-check-circle"
                          : "mdi-close-circle"
                      }}
                    </v-icon>
                  </div>
                  <div>
                    <div class="pr-review-card__round">
                      Round {{ reviews.length - rIdx }}
                      <span
                        class="pr-review-card__decision-label"
                        :class="
                          `pr-review-card__decision-label--${review.decision}`
                        "
                      >
                        {{
                          review.decision === "approved"
                            ? "Approved"
                            : "Rejected"
                        }}
                      </span>
                    </div>
                    <div class="pr-review-card__meta">
                      <v-icon size="11" color="#94a3b8"
                        >mdi-clock-outline</v-icon
                      >
                      {{ formatDate(review.date) }}
                    </div>
                  </div>
                </div>
                <v-icon
                  size="16"
                  color="#94a3b8"
                  :class="{ 'pr-rotate': expandedReviews[rIdx] }"
                >
                  mdi-chevron-down
                </v-icon>
              </div>
              <v-expand-transition>
                <div v-if="expandedReviews[rIdx]" class="pr-review-card__body">
                  <div v-if="review.comment" class="pr-review-card__comment">
                    <div class="pr-review-card__comment-label">
                      <v-icon size="12" color="#64748b"
                        >mdi-comment-text-outline</v-icon
                      >
                      Supervisor Comment
                    </div>
                    <p class="pr-review-card__comment-text">
                      {{ review.comment }}
                    </p>
                  </div>
                  <div v-else class="pr-review-card__no-comment">
                    No comment provided.
                  </div>
                </div>
              </v-expand-transition>
            </div>
          </div>
        </div>
