          ref="objectivesPanel"
          :plan-id="performancePlan ? performancePlan.id : null"
          :can-edit="canEdit"
          accent-color="orange"
          @data-loaded="onDataLoaded"
          @add-objective="addObjective"
          @edit-objective="editObjective"
          @delete-objective="(obj) => confirmDelete('objective', obj)"
          @add-activity="addActivity"
          @edit-activity="editActivity"
          @delete-activity="(act) => confirmDelete('activity', act)"
          @add-sub="addSubActivity"
          @delete-sub="(sub) => confirmDelete('sub-activity', sub)"
          @edit-sub="editSubActivity"
          @add-kpi="addKpi"
          @edit-kpi="editKpi"
          @delete-kpi="(kpi) => confirmDelete('kpi', kpi)"
          @add-target="addTarget"
          @edit-target="editTarget"
          @delete-target="(t) => confirmDelete('target', t)"
        />
      </div>
