    <!-- Create Plan Dialog -->
    <v-dialog
      v-model="showCreatePlanDialog"
      max-width="540"
      content-class="pp2-dialog"
    >
      <div class="pp2-dialog__strip pp2-dialog__strip--orange"></div>
      <div class="pp2-dialog__inner">
        <div class="pp2-dialog__head">
          <div class="pp2-dialog__head-icon pp2-dialog__head-icon--orange">
            <v-icon color="white" size="20">mdi-file-plus-outline</v-icon>
          </div>
          <div>
            <div class="pp2-dialog__title">
              {{
                newPlan.editMode
                  ? "Edit Performance Plan"
                  : "Create Performance Plan"
              }}
            </div>
            <div class="pp2-dialog__sub">
              Fiscal Year {{ selectedFiscalYear }}
            </div>
          </div>
          <button class="pp2-dialog__x" @click="showCreatePlanDialog = false">
            <v-icon size="18" color="#94a3b8">mdi-close</v-icon>
          </button>
        </div>
        <div class="pp2-dialog__body">
          <v-form ref="planForm" v-model="validPlan">
            <div class="pp2-field">
              <label class="pp2-field__lbl"
                >Plan Title <span class="pp2-req">*</span></label
              >
              <v-text-field
                v-model="newPlan.name"
                :rules="[rules.required]"
                outlined
                dense
                hide-details="auto"
                class="pp2-input"
                placeholder="e.g. FY2026 Performance Plan"
              />
            </div>
            <div class="pp2-field">
              <label class="pp2-field__lbl">Description</label>
              <v-textarea
                v-model="newPlan.description"
                outlined
                dense
                hide-details="auto"
                rows="3"
                class="pp2-input"
                placeholder="Brief description..."
              />
            </div>
          </v-form>
        </div>
        <div class="pp2-dialog__foot">
          <button
            class="pp2-btn pp2-btn--ghost"
            @click="showCreatePlanDialog = false"
          >
            Cancel
          </button>
          <button
            class="pp2-btn pp2-btn--primary"
            :disabled="!validPlan"
            @click="savePlan"
          >
            {{ newPlan.editMode ? "Save Changes" : "Create Plan" }}
          </button>
        </div>
      </div>
    </v-dialog>

    <!-- Add Objective Dialog -->
    <v-dialog
      v-model="showObjectiveDialog"
      max-width="540"
      content-class="pp2-dialog"
    >
      <div class="pp2-dialog__strip pp2-dialog__strip--teal"></div>
      <div class="pp2-dialog__inner">
        <div class="pp2-dialog__head">
          <div class="pp2-dialog__head-icon pp2-dialog__head-icon--teal">
            <v-icon color="white" size="20">mdi-target</v-icon>
          </div>
          <div>
            <div class="pp2-dialog__title">
              {{ newObjective.editMode ? "Edit Objective" : "Add Objective" }}
            </div>
            <div class="pp2-dialog__sub">Define a measurable goal</div>
          </div>
          <button class="pp2-dialog__x" @click="showObjectiveDialog = false">
            <v-icon size="18" color="#94a3b8">mdi-close</v-icon>
          </button>
        </div>
        <div class="pp2-dialog__body">
          <v-form ref="objectiveForm" v-model="validObjective">
            <div class="pp2-field">
              <label class="pp2-field__lbl"
                >Objective Title <span class="pp2-req">*</span></label
              >
              <v-text-field
                v-model="newObjective.name"
                :rules="[rules.required]"
                outlined
                dense
                hide-details="auto"
                class="pp2-input"
                placeholder="e.g. Financial Management"
              />
            </div>
            <div class="pp2-field">
              <label class="pp2-field__lbl">Description </label>
              <v-textarea
                v-model="newObjective.description"
                outlined
                dense
                hide-details="auto"
                rows="3"
                class="pp2-input"
                placeholder="Describe this objective..."
              />
            </div>
            <div class="pp2-field" v-if="!isPrincipalSecretary">
              <label class="pp2-field__lbl"
                >Link to Supervisor Activity / Sub-Activity
                <span class="pp2-req">*</span></label
              >
              <v-autocomplete
                v-model="newObjective.parentActivityId"
                :items="supervisorActivities"
                :rules="[rules.required]"
                item-text="displayName"
                item-value="id"
                outlined
                dense
                hide-details="auto"
                :loading="loadingSupervisorActivities"
                class="pp2-input"
                placeholder="Select activity or sub-activity to link to..."
                clearable
              />
              <div
                class="pp2-field__hint"
                v-if="
                  supervisorActivities.length === 0 &&
                    !loadingSupervisorActivities
                "
              >
                No supervisor activities found for this fiscal year
              </div>
            </div>
          </v-form>
        </div>
        <div class="pp2-dialog__foot">
          <button
            class="pp2-btn pp2-btn--ghost"
            @click="showObjectiveDialog = false"
          >
            Cancel
          </button>
          <button
            class="pp2-btn pp2-btn--teal"
            :disabled="!validObjective"
            @click="saveObjective"
          >
            {{ newObjective.editMode ? "Save Changes" : "Add Objective" }}
          </button>
        </div>
      </div>
    </v-dialog>

    <!-- Add Activity Dialog -->
    <v-dialog
      v-model="showActivityDialog"
      max-width="540"
      content-class="pp2-dialog"
    >
      <div class="pp2-dialog__strip pp2-dialog__strip--violet"></div>
      <div class="pp2-dialog__inner">
        <div class="pp2-dialog__head">
          <div class="pp2-dialog__head-icon pp2-dialog__head-icon--violet">
            <v-icon color="white" size="20">mdi-run-fast</v-icon>
          </div>
          <div>
            <div class="pp2-dialog__title">
              {{ newActivity.editMode ? "Edit Activity" : "Add Activity" }}
            </div>
            <div class="pp2-dialog__sub">
              Under: <strong>{{ currentObjectiveName }}</strong>
            </div>
          </div>
          <button class="pp2-dialog__x" @click="showActivityDialog = false">
            <v-icon size="18" color="#94a3b8">mdi-close</v-icon>
          </button>
        </div>
        <div class="pp2-dialog__body">
          <v-form ref="activityForm" v-model="validActivity">
            <div class="pp2-field">
              <label class="pp2-field__lbl"
                >Activity Title <span class="pp2-req">*</span></label
              >
              <v-text-field
                v-model="newActivity.name"
                :rules="[rules.required]"
                outlined
                dense
                hide-details="auto"
                class="pp2-input"
                placeholder="e.g. Monthly payroll review"
              />
            </div>
            <div class="pp2-field">
              <label class="pp2-field__lbl">Description </label>
              <v-textarea
                v-model="newActivity.description"
                outlined
                dense
                hide-details="auto"
                rows="3"
                class="pp2-input"
                placeholder="Describe this activity..."
              />
            </div>
          </v-form>
        </div>
        <div class="pp2-dialog__foot">
          <button
            class="pp2-btn pp2-btn--ghost"
            @click="showActivityDialog = false"
          >
            Cancel
          </button>
          <button
            class="pp2-btn pp2-btn--violet"
            :disabled="!validActivity"
            @click="saveActivity"
          >
            {{ newActivity.editMode ? "Save Changes" : "Add Activity" }}
          </button>
        </div>
      </div>
    </v-dialog>

    <!-- Add Sub-Activity Dialog -->
    <v-dialog
      v-model="showSubActivityDialog"
      max-width="540"
      content-class="pp2-dialog"
    >
      <div class="pp2-dialog__strip pp2-dialog__strip--amber"></div>
      <div class="pp2-dialog__inner">
        <div class="pp2-dialog__head">
          <div class="pp2-dialog__head-icon pp2-dialog__head-icon--amber">
            <v-icon color="white" size="20"
              >mdi-subdirectory-arrow-right</v-icon
            >
          </div>
          <div>
            <div class="pp2-dialog__title">
              {{
