<script>
const querystring = require("querystring");
import processQuestionnaire from "../../mixins/processQuestionnaire";
import generalMixin from "../../mixins/general";
import PerformancePlanObjectives from "./performance-plan-objectives.vue";
export default {
  name: "PerformancePlan",
  mixins: [processQuestionnaire, generalMixin],

  components: { PerformancePlanObjectives },

  data() {
    return {
      url: "http://ihris.org/fhir/Questionnaire/performance-plan",
      fhir: {},
      fhirId: "",
      profile:
        "http://ihris.org/fhir/StructureDefinition/performance-plan-profile",
      loading: false,
      selectedFiscalYear: "",
      fiscalYears: [],
      customFiscalYearInput: "",
      customFiscalYearError: "",
      windowClosedDismissed: false,
      perfConfig: null, // { isOpen, targetFY, context, hasOverride }

      performancePlan: null,
      objectives: [],
      activities: [],
      subActivities: [],
      kpis: [],
      targets: [],

      showValidationPanel: false,

      isPrincipalSecretary: false,
      supervisorActivities: [],
      loadingSupervisorActivities: false,

      currentObjectiveName: "",
      currentActivityName: "",
      currentParentName: "",
      currentFiscalYear: "",

      showCreatePlanDialog: false,
      showObjectiveDialog: false,
      showActivityDialog: false,
      showSubActivityDialog: false,
      showKpiDialog: false,
      showTargetDialog: false,
      showDeleteDialog: false,
      showSubmitPlanDialog: false,
      deleteItemType: null, // 'objective' | 'activity' | 'subactivity' | 'kpi' | 'target'
      deleteItem: null,

      validPlan: false,
      validObjective: false,
      validActivity: false,
      validSubActivity: false,
      validKpi: false,
      validTarget: false,
      // Review history
      reviews: [],
      expandedReviews: {},

      newPlan: {
        name: "",
        description: "",
        fiscalYear: "",
        editMode: false,
        editingId: null,
      },
      newObjective: {
        type: "objective",
        name: "",
        description: "",
        performancePlanId: null,
        parentActivityId: null,
        editMode: false,
        editingId: null,
      },
      newActivity: {
        type: "activity",
        name: "",
        description: "",
        parent: null,
        editMode: false,
        editingId: null,
      },
      newSubActivity: {
        type: "subactivity",
        name: "",
        description: "",
        parent: null,
        editMode: false,
        editingId: null,
      },
      newKpi: {
        type: "kpi",
        name: "",
        description: "",
        parent: null,
        editMode: false,
        editingId: null,
      },
      newTarget: {
        type: "target",
        name: "",
        description: "",
        parent: null,
        editMode: false,
        editingId: null,
      },
      supervisorTargetsByObjective: {},
      objectiveCompleteness: [], // synced from child via data-loaded
      allPlanErrors: [], // synced from child via data-loaded

      snackbar: false,
      snackbarMessage: "",
      snackbarColor: "success",
      snackbarIcon: "mdi-check-circle",
      afterSaveMessage: "",

      rules: { required: (v) => !!v || "Required" },
    };
  },

  computed: {
    isOwner() {
      return this.queries.practitioner === this.loggedInStaff.practitioner;
    },
    objectivesWithErrors() {
      return this.objectiveCompleteness.filter((oc) => oc.errors.length > 0);
    },
    queries() {
      return this.$route?.query || {};
    },

    planStatus() {
      if (!this.performancePlan) return "no-plan";
      return this.performancePlan.status || "draft";
    },

    statusLabel() {
      const map = {
        draft: "Draft",
        submitted: "Submitted",
        approved: "Approved",
        rejected: "Rejected",
        active: "Active",
        undersupervisorreview: "Under Supervisor Review",
        "no-plan": "No Plan",
      };
      return map[this.planStatus] || this.planStatus;
    },

    canEdit() {
      if (this.loggedInStaff.practitioner != this.queries.practitioner)
        return false;
      // Window must be open (or an active override exists for the selected FY)
      if (!this.goalWindowOpen) return false;
      return (
        !this.performancePlan ||
        ["draft", "rejected"].includes(this.performancePlan.status)
      );
    },

    goalWindowOpen() {
      if (!this.perfConfig) return false;
      // Config says this window targets a specific FY; allow editing that FY
      return (
        this.perfConfig.isOpen &&
        this.perfConfig.targetFY === this.selectedFiscalYear
      );
    },

    goalWindowMessage() {
      if (!this.perfConfig || this.perfConfig.isOpen) return "";
      return `The goal setting window is currently closed. Goals can only be set during the configured window.`;
    },

    hasObjectives() {
      return this.objectives.length > 0;
    },

    deleteItemTypeLabel() {
      const map = {
        objective: "Objective",
        activity: "Activity",
        subactivity: "Sub-Activity",
        kpi: "KPI",
        target: "Target",
      };
      return map[this.deleteItemType] || "";
    },

    planCanSubmit() {
      return this.objectives.length > 0 && this.allPlanErrors.length === 0;
    },
  },

  async mounted() {
    this.loading = true;
    await this.$nextTick();
    await new Promise((resolve) => {
      if (!this.loadingUserData) {
        // Already loaded
        resolve();
        return;
      }

      // Watch for loadingUserData to become false
      const unwatch = this.$watch("loadingUserData", (newValue) => {
        if (!newValue) {
          unwatch();
          resolve();
        }
      });

      // Timeout after 15 seconds
      setTimeout(() => {
        unwatch();
        console.warn("Timeout waiting for user data to load");
        resolve();
      }, 15000);
    });
    let fiscalYear = await fetch("/site/leave/getFinancialYear");
    fiscalYear = await fiscalYear.json();
    this.selectedFiscalYear = fiscalYear.year;
    this.currentFiscalYear = fiscalYear.year;

    await this.loadPerfConfig();
    await this.initialize();
    //if approved then mark notification as read
    if (this.performancePlan.status === "approved") {
      let user = this.$store.state.user?.obj?.resource?.id;
      let task = await fetch(
        `/fhir/Basic?user=${user}&usertaskstatus=pending&usertaskid=${this.queries.plan}`,
      );
      let response = await task.json();
      if (response && response.entry && response.entry.length) {
        let taskDescr = response.entry[0].resource.extension.find((ext) => {
          return (
            ext.url ===
            "http://ihris.org/fhir/StructureDefinition/user-task-description"
          );
        });
        let statusIndex = taskDescr.extension.findIndex((ext) => {
          return ext.url === "status";
        });
        taskDescr.extension[statusIndex].valueCoding.code = "done";
        taskDescr.extension[statusIndex].valueCoding.display = "Done";

        fetch("/fhir/Basic/" + response.entry[0].resource.id, {
          method: "PUT",
          headers: {
            "Content-Type": "application/fhir+json",
            Accept: "application/fhir+json",
          },
          body: JSON.stringify(response.entry[0].resource),
        });
      }
    }
  },

  methods: {
    goHome() {
      window.location.href =
        "/custom/performance?path=/lesotho/components/performance";
    },
    async loadPerfConfig() {
      try {
        const [cfgRes, ovRes] = await Promise.all([
          fetch("/fhir/Parameters/performance-config").then((r) =>
            r.ok ? r.json() : null,
          ),
          fetch("/fhir/Parameters/performance-override-config").then((r) =>
            r.ok ? r.json() : null,
          ),
        ]);
        if (!cfgRes) return;
        const shift = (fy, d) => {
          const [s, e] = fy.split("/").map(Number);
          return `${s + d}/${e + d}`;
        };
        // const todayDate = new Date("2026-03-20");
        const todayDate = new Date();
        const todayMmDd =
          String(todayDate.getMonth() + 1).padStart(2, "0") +
          "-" +
          String(todayDate.getDate()).padStart(2, "0");
        const fraction = (mmdd) => {
          if (!mmdd) return 0;
          const [mm, dd] = mmdd.split("-").map(Number);
          const mo = [0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
          return (
            (mo.slice(0, mm - 1).reduce((a, b) => a + b, 0) + dd - 1) / 365
          );
        };
        const inRange = (s, e) => {
          const t = fraction(todayMmDd),
            sf = fraction(s),
            ef = fraction(e);
          return ef < sf ? t >= sf || t <= ef : t >= sf && t <= ef;
        };
        const overrides = {};
        for (const p of ovRes?.parameter || []) {
          const g = (n) =>
            (p.part || []).find((pt) => pt.name === n)?.valueString || "";
          overrides[p.name] = {
            fiscalYear: g("fiscal-year"),
            overrideEnd: g("override-end"),
            status: g("status"),
          };
        }
        const win = (cfgRes.parameter || []).find(
          (p) => p.name === "goal-settings",
        );
        if (!win) return;
        const g = (n) =>
          (win.part || []).find((pt) => pt.name === n)?.valueString || "";
        const ctx = g("fiscal-year-context");
        const d = ctx === "next" ? 1 : ctx === "previous" ? -1 : 0;
        const derivedTargetFY = shift(this.currentFiscalYear, d);
        const baseOpen = inRange(g("start-date"), g("end-date"));
        const ov = overrides["goal-settings"];

        // An override is active if: status=active AND not yet expired.
        // We do NOT compare ov.fiscalYear against any derived value — cross-window
        // contamination is impossible because overrides are keyed by window name
        // (a goal-settings override only lives under "goal-settings"). The override's
        // own fiscalYear field is the authoritative target the admin set explicitly.
        const ovActive =
          ov?.status === "active" && new Date(ov.overrideEnd) >= todayDate;

        // When the override is active its fiscalYear is the target (admin's intent).
        // Otherwise fall back to the derived FY.
        const targetFY = ovActive ? ov.fiscalYear : derivedTargetFY;
        this.perfConfig = {
          isOpen: baseOpen || ovActive,
          targetFY,
          derivedTargetFY,
          context: ctx,
          hasOverride: ovActive,
        };
        // Switch the year selector to the target FY so the planner loads the
        // correct plan — especially important when an override extends the window
        // into the next quarter.
        if (!this.perfConfig.isOpen) {
          this.selectedFiscalYear = this.currentFiscalYear;
        } else if (targetFY && targetFY !== this.selectedFiscalYear) {
          this.selectedFiscalYear = targetFY;
        }
      } catch (e) {
        console.error("loadPerfConfig error", e);
      }
    },

    async loadPlan() {
      await this.loadPerformancePlan();
      // objectives/activities/subs/kpis/targets now loaded by
      // PerformancePlanObjectives via its planId watcher
    },

    onDataLoaded({
      objectives,
      activities,
      subActivities,
      kpis,
      targets,
      supervisorTargetsByObjective,
      objectiveCompleteness,
      allPlanErrors,
    }) {
      this.objectives = objectives;
      this.activities = activities;
      this.subActivities = subActivities;
      this.kpis = kpis;
      this.targets = targets;
      this.supervisorTargetsByObjective = supervisorTargetsByObjective;
      this.objectiveCompleteness = objectiveCompleteness;
      this.allPlanErrors = allPlanErrors;
    },
    async initialize() {
      try {
        this.generateFiscalYears();
        await this.loadPlan();
        await this.loadReviews();
        await this.checkIfPermanentSecretary();
      } catch (e) {
        this.showSnackbar("Error loading data", "error");
      } finally {
        this.loading = false;
      }
    },

    generateFiscalYears() {
      let fy = this.perfConfig.derivedTargetFY;
      this.fiscalYears = [];
      let currentYear = parseInt(fy.split("/")[0]);

      for (let i = 4; i >= 0; i--) {
        const startYear = currentYear - i;
        const endYear = startYear + 1;
        this.fiscalYears.push(`${startYear}/${endYear}`);
      }
      this.fiscalYears.sort();
    },

    applyCustomFiscalYear() {
      const val = this.customFiscalYearInput.trim();
      if (!val) {
        this.customFiscalYearError = "";
        return;
      }
      const valid = /^\d{4}\/\d{4}$/.test(val);
      if (!valid) {
        this.customFiscalYearError = "Format: YYYY/YYYY";
        return;
      }
      const [start, end] = val.split("/").map(Number);
      if (end !== start + 1) {
        this.customFiscalYearError = "End year must be start + 1";
        return;
      }
      this.customFiscalYearError = "";
      this.selectedFiscalYear = val;
      this.loadPlan();
    },

    async checkIfPermanentSecretary() {
      let ps = await fetch("/site/general/getPS");
      ps = await ps.json();
      if (ps.practitioner == this.loggedInStaff.practitioner) {
        this.isPrincipalSecretary = true;
      } else {
        this.isPrincipalSecretary = false;
      }
    },

    async loadReviews() {
      if (!this.performancePlan) return;
      try {
        const params = new URLSearchParams({
          _profile:
            "http://ihris.org/fhir/StructureDefinition/supervisor-performance-plan-review-profile",
          performanceplan: `Basic/${this.performancePlan.id}`,
          _sort: "-_lastUpdated",
        });
        const r = await fetch(`/fhir/Basic?${params}`);
        const b = await r.json();
        this.reviews = b.entry
          ? b.entry.map((e) => this.extractReviewData(e.resource))
          : [];
        if (this.reviews.length > 0) {
          this.$set(this.expandedReviews, 0, true);
        }
      } catch (e) {
        console.error(e);
      }
    },

    async loadPerformancePlan() {
      this.loading = true;
      try {
        const params = new URLSearchParams({
          _profile:
            "http://ihris.org/fhir/StructureDefinition/performance-plan-profile",
          practitioner: `Practitioner/${this.queries.practitioner}`,
          fiscalyear: this.selectedFiscalYear,
        });
        const r = await fetch(`/fhir/Basic?${params}`);
        const b = await r.json();
        if (b.entry?.length > 0) {
          this.performancePlan = this.extractPlanData(b.entry[0].resource);
        } else {
          this.performancePlan = null;
          this.objectives = [];
        }
      } catch (e) {
        this.showSnackbar("Error loading plan", "error");
      } finally {
        this.loading = false;
      }
    },

    ext(resource, url) {
      return resource.extension?.find((e) => e.url.includes(url));
    },
    extractPlanData(r) {
      return {
        id: r.id,
        name: this.ext(r, "ihris-basic-name")?.valueString || "",
        description: this.ext(r, "description")?.valueString || "",
        fiscalYear: this.ext(r, "fiscal-year")?.valueString || "",
        status: this.ext(r, "request-status")?.valueCoding?.code || "draft",
      };
    },
    extractReviewData(r) {
      return {
        id: r.id,
        comment: this.ext(r, "description")?.valueString || "",
        decision: this.ext(r, "review-status")?.valueCoding?.code || "",
        reviewerRef:
          this.ext(r, "user-reference")?.valueReference?.reference || "",
        planRef:
          this.ext(r, "performance-plan-reference")?.valueReference
            ?.reference || "",
        date: r.meta?.lastUpdated,
      };
    },
    toggleReview(index) {
      this.$set(this.expandedReviews, index, !this.expandedReviews[index]);
    },
    formatDate(dateStr) {
      if (!dateStr) return "";
      try {
        return new Intl.DateTimeFormat("en-GB", {
          day: "2-digit",
          month: "short",
          year: "numeric",
          hour: "2-digit",
          minute: "2-digit",
        }).format(new Date(dateStr));
      } catch {
        return dateStr;
      }
    },

    async createNewPlan() {
      this.newPlan = {
        name: `Performance Plan ${this.selectedFiscalYear}`,
        description: "",
        fiscalYear: this.selectedFiscalYear,
        editMode: false,
        editingId: null,
      };
      this.showCreatePlanDialog = true;
    },

    async editPlan() {
      this.newPlan = {
        name: this.performancePlan.name,
        description: this.performancePlan.description,
        fiscalYear: this.performancePlan.fiscalYear,
        parentTarget: this.performancePlan.parent
          ? this.performancePlan.parent.split("/")[1]
          : null,
        editMode: true,
        editingId: this.performancePlan.id,
      };
      if (!this.isPrincipalSecretary) await this.loadSupervisorActivities();
      this.showCreatePlanDialog = true;
    },

    async loadSupervisorActivities() {
      this.loadingSupervisorActivities = true;
      this.supervisorActivities = [];
      try {
        // Step 1: fetch supervisor's plan for this fiscal year
        const planParams = new URLSearchParams({
          _profile:
            "http://ihris.org/fhir/StructureDefinition/performance-plan-profile",
          practitioner: `${this.loggedInStaff.supervisor.practitioner}`,
          fiscalyear: this.selectedFiscalYear,
          _revinclude: "Basic:performanceplan",
          requeststatus: "approved",
        });
        let planResp = await fetch(`/fhir/Basic?${planParams}`);
        planResp = await planResp.json();
        if (!planResp.entry || !planResp.entry.length) return;

        // Step 2: collect objective IDs from the supervisor's plan
        const objectives = planResp.entry.filter((record) =>
          record.resource.meta.profile.includes(
            "http://ihris.org/fhir/StructureDefinition/performance-objective-profile",
          ),
        );
        if (!objectives.length) return;

        const objectiveIds = objectives.map((o) => o.resource.id).join(",");

        // Step 3: fetch activities + sub-activities of those objectives
        const childParams = new URLSearchParams({
          _profile:
            "http://ihris.org/fhir/StructureDefinition/performance-objective-profile",
          _id: objectiveIds,
          practitioner: `${this.loggedInStaff.supervisor.practitioner}`,
          "_revinclude:iterate": "Basic:parent",
        });
        let childResp = await fetch(`/fhir/Basic?${childParams}`);
        childResp = await childResp.json();
        if (!childResp.entry) return;

        // Step 4: map to { id, displayName } — indent sub-activities
        const getName = (resource) =>
          resource.extension.find(
            (ext) =>
              ext.url ===
              "http://ihris.org/fhir/StructureDefinition/ihris-basic-name",
          )?.valueString || resource.id;

        const acts = childResp.entry.filter((r) =>
          r.resource.meta.profile.includes(
            "http://ihris.org/fhir/StructureDefinition/performance-activity-profile",
          ),
        );
        const subs = childResp.entry.filter((r) =>
          r.resource.meta.profile.includes(
            "http://ihris.org/fhir/StructureDefinition/performance-subactivity-profile",
          ),
        );

        this.supervisorActivities = [
          ...acts.map((e) => ({
            id: e.resource.id,
            name: getName(e.resource),
            displayName: getName(e.resource),
            type: "activity",
          })),
          ...subs.map((e) => ({
            id: e.resource.id,
            name: getName(e.resource),
            displayName: "↳ " + getName(e.resource),
            type: "sub-activity",
          })),
        ];
      } catch (e) {
        console.error(e);
      } finally {
        this.loadingSupervisorActivities = false;
      }
    },

    async savePlan() {
      if (!this.$refs.planForm.validate()) return;
      this.loading = true;
      try {
        this.fhir = {
          type: "plan",
          name: this.newPlan.name,
          description: this.newPlan.description,
          fiscalYear: this.newPlan.fiscalYear,
          ...(this.newPlan.editMode && {
            id: this.newPlan.editingId,
            editMode: true,
          }),
        };
        await this.processFHIR();
        this.showCreatePlanDialog = false;
        this.showSnackbar(
          this.newPlan.editMode
            ? "Plan updated successfully"
            : "Plan created successfully",
          "success",
        );
        await this.loadPerformancePlan();
      } catch (e) {
        this.showSnackbar(
          this.newPlan.editMode ? "Error updating plan" : "Error creating plan",
          "error",
        );
      } finally {
        this.loading = false;
      }
    },

    addObjective() {
      this.newObjective = {
        type: "objective",
        name: "",
        description: "",
        performancePlanId: this.performancePlan.id,
        parentActivityId: null,
        editMode: false,
        editingId: null,
      };

      // Load supervisor targets only if not Permanent Secretary
      if (!this.isPrincipalSecretary) {
        this.loadSupervisorActivities();
      }

      this.showObjectiveDialog = true;
    },

    editObjective(objective) {
      this.newObjective = {
        type: "objective",
        name: objective.name,
        description: objective.description,
        performancePlanId: objective.performancePlanId,
        parentActivityId: objective.parentActivityId,
        objectiveid: objective.id,
      };
      if (!this.isPrincipalSecretary) {
        this.loadSupervisorActivities();
      }

      this.showObjectiveDialog = true;
    },

    async saveObjective() {
      if (!this.$refs.objectiveForm.validate()) return;
      this.loading = true;
      try {
        this.fhir = {
          type: "objective",
          name: this.newObjective.name,
          description: this.newObjective.description,
          performancePlanId: this.newObjective.performancePlanId,
          parent: this.newObjective.parentActivityId,
          objectiveid: this.newObjective.objectiveid,
        };
        await this.processFHIR();
        this.showObjectiveDialog = false;
        this.showSnackbar(
          this.newObjective.editMode ? "Objective updated" : "Objective added",
          "success",
        );
        await this.$refs.objectivesPanel.reloadObjectives();
      } catch (e) {
        this.showSnackbar(
          this.newObjective.editMode
            ? "Error updating objective"
            : "Error adding objective",
          "error",
        );
      } finally {
        this.loading = false;
      }
    },

    addActivity(obj) {
      this.currentObjectiveName = obj.name;
      this.newActivity = {
        type: "activity",
        name: "",
        description: "",
        parent: obj.id,
        editMode: false,
        editingId: null,
      };
      this.showActivityDialog = true;
    },

    editActivity(activity) {
      // Find the parent objective name for context
      const parentObj = this.objectives.find((o) => o.id === activity.parentId);
      this.currentObjectiveName = parentObj ? parentObj.name : "";
      this.newActivity = {
        type: "activity",
        name: activity.name,
        description: activity.description,
        parent: activity.parentId,
        activityid: activity.id,
      };
      this.showActivityDialog = true;
    },

    async saveActivity() {
      if (!this.$refs.activityForm.validate()) return;
      this.loading = true;
      try {
        this.fhir = {
          ...this.newActivity,
        };
        await this.processFHIR();
        this.showActivityDialog = false;
        this.showSnackbar(
          this.newActivity.editMode ? "Activity updated" : "Activity added",
          "success",
        );
        await this.$refs.objectivesPanel.reloadActivities();
      } catch (e) {
        this.showSnackbar(
          this.newActivity.editMode
            ? "Error updating activity"
            : "Error adding activity",
          "error",
        );
      } finally {
        this.loading = false;
      }
    },

    addSubActivity(act) {
      this.currentActivityName = act.name;
      this.newSubActivity = {
        type: "subactivity",
        name: "",
        description: "",
        parent: act.id,
        editMode: false,
        editingId: null,
      };
      this.showSubActivityDialog = true;
    },

    editSubActivity(sub) {
      const parentAct = this.activities.find((a) => a.id === sub.parentId);
      this.currentActivityName = parentAct ? parentAct.name : "";
      this.newSubActivity = {
        type: "subactivity",
        name: sub.name,
        description: sub.description,
        parent: sub.parentId,
        subactivityid: sub.id,
      };
      this.showSubActivityDialog = true;
    },

    async saveSubActivity() {
      if (!this.$refs.subActivityForm.validate()) return;
      this.loading = true;
      try {
        this.fhir = {
          ...this.newSubActivity,
        };
        await this.processFHIR();
        this.showSubActivityDialog = false;
        this.showSnackbar(
          this.newSubActivity.editMode
            ? "Sub-activity updated"
            : "Sub-activity added",
          "success",
        );
        await this.$refs.objectivesPanel.reloadSubActivities();
      } catch (e) {
        this.showSnackbar(
          this.newSubActivity.editMode
            ? "Error updating sub-activity"
            : "Error adding sub-activity",
          "error",
        );
      } finally {
        this.loading = false;
      }
    },

    addKpi(parent) {
      this.currentParentName = parent.name;
      this.newKpi = {
        type: "kpi",
        name: "",
        description: "",
        parent: parent.id,
        editMode: false,
        editingId: null,
      };
      this.showKpiDialog = true;
    },

    editKpi(kpi) {
      const parentAct = this.activities.find((a) => a.id === kpi.parentId);
      const parentSub = this.subActivities.find((s) => s.id === kpi.parentId);
      this.currentParentName = parentAct
        ? parentAct.name
        : parentSub
        ? parentSub.name
        : "";
      this.newKpi = {
        type: "kpi",
        name: kpi.name,
        description: kpi.description,
        parent: kpi.parentId,
        editMode: true,
        editingId: kpi.id,
      };
      this.showKpiDialog = true;
    },

    async saveKpi() {
      if (!this.$refs.kpiForm.validate()) return;
      this.loading = true;
      try {
        this.fhir = {
          ...this.newKpi,
          ...(this.newKpi.editMode && {
            kpiid: this.newKpi.editingId,
            editMode: true,
          }),
        };
        await this.processFHIR();
        this.showKpiDialog = false;
        this.showSnackbar(
          this.newKpi.editMode ? "KPI updated" : "KPI added",
          "success",
        );
        await this.$refs.objectivesPanel.reloadKpis();
      } catch (e) {
        this.showSnackbar(
          this.newKpi.editMode ? "Error updating KPI" : "Error adding KPI",
          "error",
        );
      } finally {
        this.loading = false;
      }
    },

    addTarget(kpi) {
      this.currentParentName = kpi.name;
      this.newTarget = {
        type: "target",
        name: "",
        description: "",
        parent: kpi.id,
        editMode: false,
        editingId: null,
      };
      this.showTargetDialog = true;
    },

    editTarget(target) {
      const parentKpi = this.kpis.find((k) => k.id === target.parentId);
      this.currentParentName = parentKpi ? parentKpi.name : "";
      this.newTarget = {
        type: "target",
        name: target.name,
        description: target.description,
        parent: target.parentId,
        targetid: target.id,
      };
      this.showTargetDialog = true;
    },

    async saveTarget() {
      if (!this.$refs.targetForm.validate()) return;
      this.loading = true;
      try {
        this.fhir = {
          ...this.newTarget,
        };
        await this.processFHIR();
        this.showTargetDialog = false;
        this.showSnackbar(
          this.newTarget.editMode ? "Target updated" : "Target added",
          "success",
        );
        await this.$refs.objectivesPanel.reloadTargets();
      } catch (e) {
        this.showSnackbar(
          this.newTarget.editMode
            ? "Error updating target"
            : "Error adding target",
          "error",
        );
      } finally {
        this.loading = false;
      }
    },
    confirmDelete(type, item) {
      this.deleteItemType = type;
      this.deleteItem = item;
      this.showDeleteDialog = true;
    },

    async executeDelete() {
      if (!this.deleteItem || !this.deleteItemType) return;
      this.loading = true;
      let bundle = {
        resourceType: "Bundle",
        type: "transaction",
        entry: [],
      };
      try {
        let params = querystring.stringify({
          _id: this.deleteItem.id,
          "_revinclude:iterate": "Basic:parent",
          practitioner: this.queries.practitioner,
        });
        let records = await fetch("/fhir/Basic?" + params);
        records = await records.json();
        let objectives = records.entry.filter((record) => {
          return record.resource.meta.profile.includes(
            "http://ihris.org/fhir/StructureDefinition/performance-objective-profile",
          );
        });
        let activities = records.entry.filter((record) => {
          return record.resource.meta.profile.includes(
            "http://ihris.org/fhir/StructureDefinition/performance-activity-profile",
          );
        });
        let subs = records.entry.filter((record) => {
          return record.resource.meta.profile.includes(
            "http://ihris.org/fhir/StructureDefinition/performance-subactivity-profile",
          );
        });
        let kpis = records.entry.filter((record) => {
          return record.resource.meta.profile.includes(
            "http://ihris.org/fhir/StructureDefinition/performance-kpi-profile",
          );
        });
        let targets = records.entry.filter((record) => {
          return record.resource.meta.profile.includes(
            "http://ihris.org/fhir/StructureDefinition/performance-target-profile",
          );
        });

        // Delete in reverse-dependency order: targets → KPIs → subs → activities → objectives
        for (let target of targets) {
          bundle.entry.push({
            resource: target.resource,
            request: { method: "DELETE", url: "Basic/" + target.resource.id },
          });
        }
        for (let kpi of kpis) {
          bundle.entry.push({
            resource: kpi.resource,
            request: { method: "DELETE", url: "Basic/" + kpi.resource.id },
          });
        }
        for (let sub of subs) {
          bundle.entry.push({
            resource: sub.resource,
            request: { method: "DELETE", url: "Basic/" + sub.resource.id },
          });
        }
        for (let activity of activities) {
          bundle.entry.push({
            resource: activity.resource,
            request: { method: "DELETE", url: "Basic/" + activity.resource.id },
          });
        }
        for (let objective of objectives) {
          bundle.entry.push({
            resource: objective.resource,
            request: {
              method: "DELETE",
              url: "Basic/" + objective.resource.id,
            },
          });
        }
        await fetch("/site/performance/deletePlan", {
          method: "DELETE",
          headers: {
            "Content-Type": "application/fhir+json",
          },
          redirect: "manual",
          body: JSON.stringify(bundle),
        });
        this.showDeleteDialog = false;
        this.showSnackbar(
          `${this.deleteItemTypeLabel} deleted successfully`,
          "success",
        );
        this.refreshData();
      } catch (e) {
        console.error("Delete error:", e);
        this.showSnackbar(
          `Error deleting ${this.deleteItemTypeLabel.toLowerCase()}`,
          "error",
        );
      } finally {
        this.loading = false;
        this.deleteItem = null;
        this.deleteItemType = null;
      }
    },

    async submitPlan() {
      if (!this.planCanSubmit) {
        this.showValidationPanel = true;
        this.showSnackbar(
          `${this.allPlanErrors.length} issue(s) must be resolved before submitting`,
          "warning",
        );
        return;
      }
      this.loading = true;
      this.showSubmitPlanDialog = false;
      this.afterSaveMessage = "Plan submitted successfully.";
      this.fhir = {
        type: "submission",
        planid: this.performancePlan.id,
      };
      try {
        await this.processFHIR();
        await this.loadPerformancePlan();
      } catch (error) {
        this.showSnackbar(
          "An error occured while submitting plan to supervisor",
          "error",
        );
      } finally {
        this.loading = false;
      }
    },
    async refreshData() {
      await this.loadPerformancePlan();
      if (this.$refs.objectivesPanel) await this.$refs.objectivesPanel.reload();
      this.showSnackbar("Refreshed", "success");
    },

    showSnackbar(message, color) {
      this.snackbarMessage = message;
      this.snackbarColor = color;
      const icons = {
        success: "mdi-check-circle",
        error: "mdi-alert-circle",
        warning: "mdi-alert",
        info: "mdi-information",
      };
      this.snackbarIcon = icons[color] || "mdi-information";
      this.snackbar = true;
    },
  },
};
</script>

