  border: 1px solid rgba(249, 115, 22, 0.3);
}
.pp2-hero__status--undersupervisorreview {
  background: rgba(249, 115, 22, 0.2);
  color: #e7c3a4;
  border: 1px solid rgba(249, 115, 22, 0.3);
}
.pp2-hero__status--approved {
  background: rgba(16, 185, 129, 0.2);
  color: #34d399;
  border: 1px solid rgba(16, 185, 129, 0.3);
}
.pp2-hero__status--rejected {
  background: rgba(239, 68, 68, 0.2);
  color: #f87171;
  border: 1px solid rgba(239, 68, 68, 0.3);
}
.pp2-hero__status--active {
  background: rgba(59, 130, 246, 0.2);
  color: #60a5fa;
  border: 1px solid rgba(59, 130, 246, 0.3);
}

/* Hero Right */
.pp2-hero__right {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 16px;
}
.pp2-hero__stats {
  display: flex;
  align-items: center;
  gap: 0;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 14px;
  overflow: hidden;
  padding: 0;
}
.pp2-hero__stat {
  padding: 14px 24px;
  text-align: center;
}
.pp2-hero__stat-div {
  width: 1px;
  height: 40px;
  background: rgba(255, 255, 255, 0.08);
}
.pp2-hero__stat-num {
  font-size: 28px;
  font-weight: 800;
  color: white;
  font-family: "JetBrains Mono", monospace;
  line-height: 1;
  letter-spacing: -0.04em;
}
.pp2-hero__stat-label {
  font-size: 11px;
  color: #e5cfbf;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  margin-top: 3px;
  font-weight: 600;
}
.pp2-hero__actions {
  display: flex;
  align-items: center;
  gap: 10px;
}

/* Year Tabs */
.pp2-year-tabs {
  display: flex;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 10px;
  padding: 3px;
  gap: 2px;
}
.pp2-year-tab {
  padding: 5px 12px;
  border-radius: 7px;
  border: none;
  background: transparent;
  color: #c9a68c;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  font-family: "JetBrains Mono", monospace;
  transition: all 0.15s;
  letter-spacing: -0.02em;
}
.pp2-year-tab:hover {
  color: #a8a29e;
}
.pp2-year-tab--active {
  background: #f97316 !important;
  color: white !important;
}
.pp2-year-custom {
  display: flex;
  flex-direction: column;
  position: relative;
}
.pp2-year-custom__input {
  padding: 5px 10px;
  border-radius: 7px;
  border: 1px solid rgba(255, 255, 255, 0.18);
  background: rgba(255, 255, 255, 0.06);
  color: rgba(255, 255, 255, 0.7);
  font-size: 11px;
  font-family: "JetBrains Mono", monospace;
  width: 90px;
  outline: none;
  transition: all 0.15s;
}
.pp2-year-custom__input::placeholder {
  color: rgba(255, 255, 255, 0.3);
}
.pp2-year-custom__input:focus {
  border-color: rgba(249, 115, 22, 0.5);
  background: rgba(249, 115, 22, 0.08);
  color: white;
}
.pp2-year-custom__input--active {
  background: #f97316 !important;
  color: white !important;
  border-color: #f97316 !important;
}
.pp2-year-custom__input--error {
  border-color: #ef4444 !important;
}
.pp2-year-custom__err {
  font-size: 9px;
  color: #f87171;
  margin-top: 2px;
  position: absolute;
  top: 100%;
  left: 0;
  white-space: nowrap;
}

/* ===== BODY ===== */
.pp2-body {
  max-width: 1200px;
  margin: 0 auto;
  padding: 32px;
}

/* ===== EMPTY STATE ===== */
.pp2-empty {
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 50vh;
}
.pp2-empty__card {
  background: white;
  border-radius: 24px;
  padding: 56px 48px;
  text-align: center;
  max-width: 480px;
  border: 1.5px solid #e7e5e4;
  box-shadow: 0 8px 40px rgba(0, 0, 0, 0.06);
}
.pp2-empty__illustration {
  position: relative;
  width: 120px;
  height: 120px;
  margin: 0 auto 28px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.pp2-empty__circle {
  position: absolute;
  border-radius: 50%;
  border: 2px solid;
}
.pp2-empty__circle--1 {
  width: 64px;
  height: 64px;
  border-color: rgba(249, 115, 22, 0.25);
}
.pp2-empty__circle--2 {
  width: 90px;
  height: 90px;
  border-color: rgba(249, 115, 22, 0.15);
  animation: pp2Pulse 2.5s ease-in-out infinite;
}
.pp2-empty__circle--3 {
  width: 116px;
  height: 116px;
  border-color: rgba(249, 115, 22, 0.08);
  animation: pp2Pulse 2.5s ease-in-out infinite 0.5s;
}
@keyframes pp2Pulse {
  0%,
  100% {
    transform: scale(1);
  }
  50% {
    transform: scale(1.04);
  }
}
.pp2-empty__icon {
  position: relative;
  z-index: 1;
}
.pp2-empty__title {
  font-size: 22px;
  font-weight: 800;
  color: #1c1917;
  letter-spacing: -0.03em;
  margin: 0 0 10px;
}
.pp2-empty__desc {
  font-size: 14px;
  color: #78716c;
  line-height: 1.65;
  margin: 0 0 28px;
}
.pp2-empty__desc strong {
  color: #292524;
  font-weight: 700;
}

/* ===== TOOLBAR ===== */
.pp2-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: white;
  border: 1.5px solid #e7e5e4;
  border-radius: 14px;
  padding: 12px 18px;
  margin-bottom: 24px;
  flex-wrap: wrap;
  gap: 12px;
}
.pp2-toolbar__left {
  display: flex;
  align-items: center;
  gap: 16px;
  flex-wrap: wrap;
}
.pp2-toolbar__crumb {
  display: flex;
  align-items: center;
  gap: 5px;
  font-size: 13px;
  color: #78716c;
  font-weight: 600;
}
.pp2-toolbar__right {
  display: flex;
  align-items: center;
  gap: 8px;
}

/* ===== EMPTY OBJECTIVES ===== */
.pp2-empty-objectives {
  background: white;
  border: 2px dashed #e7e5e4;
  border-radius: 16px;
  padding: 48px;
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
}
.pp2-empty-objectives h3 {
  font-size: 17px;
  font-weight: 700;
  color: #292524;
  margin: 8px 0 0;
}
.pp2-empty-objectives p {
  font-size: 13px;
  color: #a8a29e;
  margin: 0 0 16px;
}

/* ===== OBJECTIVES GRID ===== */
.pp2-objectives {
  display: flex;
  gap: 16px;
  align-items: flex-start;
}
.pp2-objectives__col {
  flex: 1 1 0;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

@media (max-width: 960px) {
  .pp2-objectives {
    flex-direction: column;
  }
  .pp2-objectives__col {
    width: 100%;
  }
}

/* ===== OBJECTIVE CARD ===== */
.pp2-obj-card {
  border-radius: 18px;
  overflow: hidden;
  border: 1.5px solid #e7e5e4;
  background: white;
  box-shadow: 0 2px 12px rgba(0, 0, 0, 0.04);
  transition: box-shadow 0.2s, transform 0.2s;
}
.pp2-obj-card:hover {
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.1);
  transform: translateY(-2px);
}

.pp2-obj-card__header {
  padding: 20px 20px 16px;
  position: relative;
}
.pp2-obj-card__header-top {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 14px;
}
.pp2-obj-card__num {
  font-family: "JetBrains Mono", monospace;
  font-size: 13px;
  font-weight: 700;
  color: rgba(255, 255, 255, 0.4);
  letter-spacing: -0.02em;
  flex-shrink: 0;
}
.pp2-obj-card__badges {
  display: flex;
  align-items: center;
  gap: 6px;
  flex: 1;
  flex-wrap: wrap;
}
.pp2-obj-card__activity-badge {
  font-size: 11px;
  font-weight: 600;
  padding: 3px 9px;
  border-radius: 20px;
  background: rgba(255, 255, 255, 0.1);
  color: rgba(255, 255, 255, 0.6);
}
.pp2-obj-card__header-actions {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-left: auto;
}
.pp2-obj-add-btn {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 5px 10px;
  border-radius: 7px;
  border: 1px solid rgba(255, 255, 255, 0.2);
  background: rgba(255, 255, 255, 0.1);
  color: white;
  font-size: 11px;
  font-weight: 700;
  cursor: pointer;
  font-family: "Sora", sans-serif;
  transition: background 0.15s;
}
.pp2-obj-add-btn:hover {
  background: rgba(255, 255, 255, 0.2);
}
.pp2-obj-card__title {
  font-size: 18px;
  font-weight: 800;
  color: white;
  letter-spacing: -0.03em;
  line-height: 1.2;
  margin: 0 0 6px;
}
.pp2-obj-card__desc {
  font-size: 13px;
  color: rgba(255, 255, 255, 0.6);
  line-height: 1.5;
  margin: 0;
}
.pp2-obj-card__body {
  padding: 16px;
}
.pp2-obj-card__empty {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 13px;
  color: #a8a29e;
  padding: 8px 0;
}
.pp2-obj-card__empty a {
  color: #f97316;
  cursor: pointer;
  font-weight: 600;
}
.pp2-obj-card__footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 20px;
  background: #fafaf8;
  border-top: 1px solid #f5f5f4;
  font-size: 12px;
  color: #a8a29e;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s;
}
.pp2-obj-card__footer:hover {
  background: #f5f5f4;
}

/* ===== ACTIVITIES LIST ===== */
.pp2-activities-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.pp2-activity {
  background: #fafaf8;
  border: 1.5px solid #e7e5e4;
  border-radius: 12px;
  overflow: hidden;
}
.pp2-activity__row {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 10px 12px;
}
.pp2-activity__index {
  font-family: "JetBrains Mono", monospace;
  font-size: 10px;
  font-weight: 700;
  color: #a8a29e;
  background: #f5f5f4;
  padding: 3px 6px;
  border-radius: 5px;
  flex-shrink: 0;
  margin-top: 2px;
}
.pp2-activity__info {
  flex: 1;
  min-width: 0;
}
.pp2-activity__name {
  font-size: 13px;
  font-weight: 700;
  color: #1c1917;
  letter-spacing: -0.01em;
}
.pp2-activity__desc {
  font-size: 11px;
  color: #a8a29e;
  margin-top: 2px;
  line-height: 1.4;
}
.pp2-activity__add-row {
  display: flex;
  gap: 5px;
  flex-shrink: 0;
  align-items: center;
}

/* Sub-Activities */
.pp2-subs {
  border-top: 1px dashed #e7e5e4;
  padding: 8px 12px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  background: #fffaf7;
}
.pp2-sub {
  display: flex;
  align-items: center;
  gap: 8px;
}
.pp2-sub__line {
  width: 16px;
  height: 1px;
  background: #f59e0b;
  flex-shrink: 0;
}
.pp2-sub__index {
  font-family: "JetBrains Mono", monospace;
  font-size: 10px;
  color: #d97706;
  background: #fef3c7;
  padding: 2px 5px;
  border-radius: 4px;
  flex-shrink: 0;
}
.pp2-sub__name {
  font-size: 12px;
  font-weight: 600;
  color: #78350f;
  flex: 1;
}

/* Targets Row */
.pp2-targets-row {
  border-top: 1px dashed #e7e5e4;
  padding: 8px 12px;
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  background: #f0fdf4;
}
.pp2-target-chip {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  background: white;
  border: 1px solid #bbf7d0;
  color: #166534;
  font-size: 11px;
  font-weight: 600;
  padding: 4px 10px;
  border-radius: 20px;
}

/* ===== DIALOGS ===== */
.pp2-dialog {
  border-radius: 20px !important;
  overflow: hidden;
  box-shadow: 0 30px 80px rgba(0, 0, 0, 0.18) !important;
}
.pp2-dialog__strip {
  height: 4px;
}
.pp2-dialog__strip--orange {
  background: linear-gradient(90deg, #f97316, #ea580c);
}
.pp2-dialog__strip--teal {
  background: linear-gradient(90deg, #0d9488, #0891b2);
}
.pp2-dialog__strip--violet {
  background: linear-gradient(90deg, #7c3aed, #6d28d9);
}
.pp2-dialog__strip--amber {
  background: linear-gradient(90deg, #f59e0b, #d97706);
}
.pp2-dialog__strip--emerald {
  background: linear-gradient(90deg, #059669, #0d9488);
}
.pp2-dialog__inner {
  background: white;
}
.pp2-dialog__head {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 22px 24px 18px;
  border-bottom: 1px solid #f5f5f4;
  position: relative;
}
.pp2-dialog__head-icon {
  width: 42px;
  height: 42px;
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.pp2-dialog__head-icon--orange {
  background: linear-gradient(135deg, #f97316, #ea580c);
}
.pp2-dialog__head-icon--teal {
  background: linear-gradient(135deg, #0d9488, #0891b2);
}
.pp2-dialog__head-icon--violet {
  background: linear-gradient(135deg, #7c3aed, #6d28d9);
}
.pp2-dialog__head-icon--amber {
  background: linear-gradient(135deg, #f59e0b, #d97706);
}
.pp2-dialog__head-icon--emerald {
  background: linear-gradient(135deg, #059669, #0d9488);
}
.pp2-dialog__title {
  font-size: 17px;
  font-weight: 800;
  color: #1c1917;
  letter-spacing: -0.03em;
}
.pp2-dialog__sub {
  font-size: 12px;
  color: #a8a29e;
  margin-top: 1px;
}
.pp2-dialog__sub strong {
  font-weight: 700;
  color: #78716c;
}
.pp2-dialog__x {
  position: absolute;
  right: 20px;
  top: 50%;
  transform: translateY(-50%);
  width: 30px;
  height: 30px;
  border-radius: 8px;
  border: 1.5px solid #e7e5e4;
  background: white;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.15s;
}
.pp2-dialog__x:hover {
  background: #f5f5f4;
}
.pp2-dialog__body {
  padding: 22px 24px;
}
.pp2-dialog__foot {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  padding: 16px 24px;
  border-top: 1px solid #f5f5f4;
  background: #fafaf8;
}

/* ===== FIELDS ===== */
.pp2-field {
  margin-bottom: 18px;
}
.pp2-field__lbl {
  display: block;
  font-size: 12px;
  font-weight: 700;
  color: #57534e;
  margin-bottom: 7px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}
.pp2-req {
  color: #f97316;
}

/* Vuetify override */
.pp2-input >>> .v-input__control .v-input__slot {
  border-radius: 10px !important;
  font-family: "Sora", sans-serif !important;
  font-size: 14px !important;
  background: white !important;
}

/* ===== BUTTONS ===== */
.pp2-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 10px 20px;
  border-radius: 10px;
  font-size: 13px;
  font-weight: 700;
  font-family: "Sora", sans-serif;
  cursor: pointer;
  border: none;
  transition: all 0.15s;
  letter-spacing: -0.01em;
  white-space: nowrap;
}
.pp2-btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}
.pp2-btn--primary {
  background: #f97316;
  color: white;
}
.pp2-btn--primary:hover:not(:disabled) {
  background: #ea580c;
  box-shadow: 0 4px 16px rgba(249, 115, 22, 0.4);
}
.pp2-btn--teal {
  background: #0d9488;
  color: white;
}
.pp2-btn--teal:hover:not(:disabled) {
  background: #0f766e;
  box-shadow: 0 4px 16px rgba(13, 148, 136, 0.4);
}
.pp2-btn--violet {
  background: #7c3aed;
  color: white;
}
.pp2-btn--violet:hover:not(:disabled) {
  background: #6d28d9;
  box-shadow: 0 4px 16px rgba(124, 58, 237, 0.4);
}
.pp2-btn--amber {
  background: #f59e0b;
  color: white;
}
.pp2-btn--amber:hover:not(:disabled) {
  background: #d97706;
  box-shadow: 0 4px 16px rgba(245, 158, 11, 0.4);
}
.pp2-btn--emerald {
  background: #059669;
  color: white;
}
.pp2-btn--emerald:hover:not(:disabled) {
  background: #047857;
  box-shadow: 0 4px 16px rgba(5, 150, 105, 0.4);
}
.pp2-btn--outline {
  background: white;
  color: #292524;
  border: 1.5px solid #e7e5e4;
}
.pp2-btn--outline:hover:not(:disabled) {
  border-color: #d6d3d1;
  background: #fafaf8;
}
.pp2-btn--ghost {
  background: transparent;
  color: #78716c;
  border: 1.5px solid #e7e5e4;
}
.pp2-btn--ghost:hover {
  background: #fafaf8;
}
.pp2-btn--sm {
  padding: 7px 14px;
  font-size: 12px;
  border-radius: 8px;
}

/* Micro Buttons */
.pp2-micro-btn {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  padding: 3px 8px;
  border-radius: 20px;
  font-size: 10px;
  font-weight: 700;
  cursor: pointer;
  border: 1.5px solid;
  font-family: "Sora", sans-serif;
  transition: all 0.15s;
  white-space: nowrap;
}
.pp2-micro-btn--amber {
  color: #d97706;
  border-color: #fde68a;
  background: #fffbeb;
}
.pp2-micro-btn--amber:hover {
  background: #fef3c7;
}
.pp2-micro-btn--emerald {
  color: #059669;
  border-color: #a7f3d0;
  background: #ecfdf5;
}
.pp2-micro-btn--emerald:hover {
  background: #d1fae5;
}

/* Icon Button */
.pp2-icon-btn {
  width: 34px;
  height: 34px;
  border-radius: 9px;
  border: none;
  background: rgba(255, 255, 255, 0.08);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: background 0.15s;
}
.pp2-icon-btn:hover {
  background: rgba(255, 255, 255, 0.14);
}
.pp2-icon-btn--sm {
  width: 28px;
  height: 28px;
  border-radius: 7px;
}
.pp2-rotate {
  transform: rotate(180deg);
  transition: transform 0.25s;
}
/* Sub-Activities Targets Styling */
.pp2-sub-targets-wrapper {
  border-top: 1px dashed #fed7aa;
  margin-top: 4px;
  padding: 8px 12px 4px 24px;
  background: #fffaf7;
}

.pp2-sub-targets-group {
  margin-bottom: 12px;
}

.pp2-sub-targets-group:last-child {
  margin-bottom: 0;
}

.pp2-sub-targets__header {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 6px;
}

.pp2-sub-targets__label {
  font-size: 11px;
  font-weight: 600;
  color: #b45309;
  letter-spacing: -0.01em;
}

.pp2-sub-targets-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-left: 18px;
}

/* Targets for Activity */
.pp2-targets-row {
  border-top: 1px dashed #bbf7d0;
  padding: 10px 12px;
  background: #f0fdf4;
}

.pp2-targets-group__header {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 8px;
}

.pp2-targets-group__label {
  font-size: 11px;
  font-weight: 600;
  color: #047857;
  text-transform: uppercase;
  letter-spacing: 0.03em;
}

.pp2-targets-container {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-left: 18px;
}

.pp2-target-chip {
  display: inline-flex;
  align-items: center;
  gap: 5px;
